constraints:
1 ≤ N ≤ 10^{5}
1 ≤ L ≤ R ≤ 10^{6}

expected time complexity: O(N).
expected auxiliary space: O(1).

standard_solution_code:
def mgc(n):
	return n * (n + 1) // 2

class Solution:

	def countSubarrays(self, a, n, L, R):
		(fp, lp) = (0, 0)
		ans = 0
		prev = 0
		while lp < n:
			if a[lp] >= L and a[lp] <= R:
				prev = lp - fp + 1
			elif a[lp] > R:
				prev = 0
				fp = lp + 1
			lp += 1
			ans += prev
		return ans
